from __future__ import annotations
import base64
from pathlib import Path

MODEL_FILES = {
    'binary_model_bundle.joblib': ('b64', ''),
    'platform_model_bundle.joblib': ('b64', ''),
    'binary_top_features.csv': ('text', '\ufefffeature,importance\nis_png,0.8422357626586113\nis_jpeg,0.8422357438237477\nexif_present,0.5728313600179161\ninfo_key_count,0.508969244143698\nband_count,0.3477624538658011\nhas_alpha,0.3477624538658011\norig_width,0.3410228009334941\naspect_ratio,0.3181685327856386\nmegapixels,0.2447572473243511\norig_height,0.24160336547209169\nhist_g_0,0.17207038415290088\nfile_size_kb,0.12810856538926468\nhist_g_6,0.09805150388199986\nmean_g,0.09646152582577641\nhist_r_4,0.09383240122959285\nstd_g,0.0878503653825384\nhist_r_2,0.08703101659680648\nedge_mean,0.08563710725732075\nhist_r_0,0.07112225127962217\nhist_r_6,0.06934258108806471\n'),
    'platform_top_features.csv': ('text', '\ufefffeature,importance\ninfo_key_count,0.34752728040980496\naspect_ratio,0.2978574318067932\nfile_size_kb,0.29349718911065537\nmegapixels,0.25723504450725754\nband_count,0.2491243499973352\nhas_alpha,0.2491243441300095\nexif_present,0.24864769421109306\nfile_size_log,0.23035003240765928\norig_height,0.22430840546331532\norig_width,0.22214409075993255\nhist_b_0,0.16326622974442856\nstd_b,0.15361360793694903\nhist_r_6,0.13956184738695604\nhist_r_5,0.1351114845366882\nhist_g_7,0.13441903298721014\nchannel_corr_rg,0.123950338954894\nhist_b_7,0.12207574684442979\nhist_r_7,0.11559476977358633\ngray_p90,0.11511548507225358\nhist_g_5,0.11161917062416025\n'),
}

def ensure_model_artifacts(root: Path) -> Path:
    model_dir = root / "model_artifacts"
    model_dir.mkdir(parents=True, exist_ok=True)
    for name, (kind, content) in MODEL_FILES.items():
        target = model_dir / name
        if target.exists():
            continue
        if kind == "b64":
            target.write_bytes(base64.b64decode(content.encode("ascii")))
        else:
            target.write_text(content, encoding="utf-8")
    return model_dir
